package com.playsphere.chat;import jakarta.persistence.*;import java.io.Serializable;import java.time.Instant;import java.util.Objects;
@Entity @Table(name="conversation_members") @IdClass(ConversationMember.Key.class) public class ConversationMember{@Id @Column(name="conversation_id",length=36)private String conversationId;@Id @Column(name="user_id",length=36)private String userId;@Column(name="joined_at",nullable=false)private Instant joinedAt;protected ConversationMember(){}public ConversationMember(String c,String u){conversationId=c;userId=u;joinedAt=Instant.now();}public String getConversationId(){return conversationId;}public String getUserId(){return userId;}public Instant getJoinedAt(){return joinedAt;}public static class Key implements Serializable{public String conversationId;public String userId;public Key(){}public boolean equals(Object o){return o instanceof Key k&&Objects.equals(conversationId,k.conversationId)&&Objects.equals(userId,k.userId);}public int hashCode(){return Objects.hash(conversationId,userId);}}}
